```cpp
#include <wx/wx.h>
#include <wx/grid.h>

class MyFrame : public wxFrame {
public:
    MyFrame() {
        // Initialize the grid
        wxGrid* grid = new wxGrid(this, wxID_ANY);
        grid->CreateGrid(5, 3); // 5 rows, 3 columns
        grid->SetColLabelValue(0, "Name");
        grid->SetColLabelValue(1, "Age");
        grid->SetColLabelValue(2, "City");

        // Set some sample data
        for (int row = 0; row < 5; row++) {
            grid->SetCellValue(row, 0, "Name" + wxString::Format("%d", row));
            grid->SetCellValue(row, 1, wxString::Format("%d", row * 10));
            grid->SetCellValue(row, 2, "City" + wxString::Format("%d", row));
        }

        // Bind a button to demonstrate getting the value
        wxButton* button = new wxButton(this, wxID_ANY, "Get Value");
        wxEventHashTable events;
        events.Add(wxEVT_BUTTON, wxEventBinder(wxEVT_BUTTON, wxID_ANY), &MyFrame::OnGetCellValue, this);
        this->Bind(events);
    }

private:
    void OnGetCellValue(wxCommandEvent& event) {
        // Assume we want to get the value from the 2nd row and "Age" column
        wxString columnName = "Age";
        int columnIndex = FindColumnIndex(columnName);
        if (columnIndex != -1) {
            wxString value = GetCellValue(2, columnIndex);
            wxLogMessage("Value at row 2, column '%s': %s", columnName, value);
        } else {
            wxLogMessage("Column '%s' not found", columnName);
        }
    }

    int FindColumnIndex(const wxString& columnLabel) {
        int colCount = GetGridColCount();
        for (int i = 0; i < colCount; ++i) {
            if (GetColLabelValue(i) == columnLabel) {
                return i;
            }
        }
        return -1; // Column not found
    }

    wxString GetCellValue(int row, int col) {
        return GetGridCellReadOnlyValue(row, col);
    }
};

class MyApp : public wxApp {
public:
    virtual bool OnInit() {
        MyFrame* frame = new MyFrame();
        frame->Show(true);
        return true;
    }
};

wxIMPLEMENT_APP(MyApp);
```

